{"code": "const cmd = [
  "echo '--- py launcher ---'; py -0 2>&1 | head -10",
  "echo '--- uv ---'; uv --version 2>&1 | head -3",
  "echo '--- pip ---'; python -m pip --version 2>&1",
  "echo '--- git ---'; git --version",
  "echo '--- node ---'; node --version"
].join("; ");
const r = await tools.ops_bash({ command: cmd, description: "Check python/uv/git/node versions", workdir: "D:\\Caliper", timeoutMs: 60000 });
console.log(r.kind === "foreground" ? r.stdout.text + "\n[stderr]\n" + r.stderr.text : JSON.stringify(r));", "description": "Check local toolchain versions"}

{"code": "const cmd = [
  "echo '--- uv located? ---'; ls -1 \"$USERPROFILE/.local/bin/uv.exe\" \"$USERPROFILE/.cargo/bin/uv.exe\" 2>/dev/null; where uv 2>/dev/null",
  "echo '--- py311 ---'; py -V:Astral/CPython3.11.15 -c \"import sys,sqlite3;print(sys.version);print('fts5', [r for r in sqlite3.connect(':memory:').execute(\\\"select 1 from pragma_compile_options where compile_options='ENABLE_FTS5'\\\")])\" 2>&1 | head -5",
  "echo '--- pypi probe ---'; timeout 25 python -m pip index versions sqlite-vec --timeout 6 2>&1 | head -3"
].join("; ");
const r = await tools.ops_bash({ command: cmd, description: "Locate uv, probe python 3.11 and PyPI", workdir: "D:\\Caliper", timeoutMs: 90000 });
console.log(r.kind === "foreground" ? r.stdout.text + "\n[stderr]\n" + r.stderr.text : JSON.stringify(r));", "description": "Locate uv and probe PyPI reachability"}

